(function(){'use strict';const DEFAULTS={enabled:true,controllerSelector:'[data-switcher]',defaultIndex:1,warnOnMismatch:true,scopeSelector:'section',modeAttribute:'data-switcher-mode',clusterTargetAttribute:'data-switcher-cluster',clusterScopeSelector:'.site-main'};const externalOptions=(typeof window!=='undefined'&&window.CarrdPluginOptions&&window.CarrdPluginOptions.switcher)||{};const CONFIG={...DEFAULTS,...externalOptions};const SELECTORS={controller:'theme-switcher-controller',button:'theme-switcher-button',panel:'theme-switcher-panel',active:'is-active',inactive:'is-inactive'};const instances=new Map();const safeNamePattern=/^[a-zA-Z][a-zA-Z0-9_-]*$/;function warn(message,context){if(!CONFIG.warnOnMismatch&&!/invalid|empty/i.test(message))return;if(typeof console!=='undefined'&&console.warn){console.warn(`Switcher: ${message}`,context||'');}}function cssEscape(value){if(window.CSS&&typeof window.CSS.escape==='function'){return window.CSS.escape(value);}return value.replace(/[^a-zA-Z0-9_-]/g,'\\$&');}function getMode(controller){return(controller.getAttribute(CONFIG.modeAttribute)||'class-index').trim();}function getScope(controller,mode){if(mode==='cluster'){if(CONFIG.clusterScopeSelector){const clusterScope=controller.closest(CONFIG.clusterScopeSelector);if(clusterScope)return clusterScope;}return controller.closest('.site-main')||document;}if(CONFIG.scopeSelector){const configuredScope=controller.closest(CONFIG.scopeSelector);if(configuredScope)return configuredScope;}return controller.closest('section')||controller.closest('.site-main')||document;}function getButtons(controller){return Array.from(controller.querySelectorAll('a[role="button"], a'));}function findClassTargets(scope,switcherName,index){const targetClass=`${switcherName}-${index}`;return Array.from(scope.querySelectorAll(`.${cssEscape(targetClass)}`));}function normalizeClusterName(value){return(value||'').trim().replace(/&quot;/g,'"').replace(/^["']+|["']+$/g,'');}function isClusterTarget(element,switcherName){return normalizeClusterName(element.getAttribute(CONFIG.clusterTargetAttribute))===switcherName;}function hasClusterTargetAncestor(element,switcherName,scope){let parent=element.parentElement;while(parent&&parent!==scope){if(isClusterTarget(parent,switcherName))return true;parent=parent.parentElement;}return false;}function findClusterTargets(scope,switcherName){return Array.from(scope.querySelectorAll(`[${CONFIG.clusterTargetAttribute}]`)).filter(target=>isClusterTarget(target,switcherName)).filter(target=>!hasClusterTargetAncestor(target,switcherName,scope));}function buildGroups(scope,switcherName,buttons,mode,controller){if(mode==='cluster'){const clusterTargets=findClusterTargets(scope,switcherName).filter(target=>target!==controller);if(clusterTargets.length>buttons.length){warn(`cluster "${switcherName}" has ${clusterTargets.length} targets for ${buttons.length} buttons; extra targets are not switchable`,controller);}return buttons.map((button,index)=>({index:index+1,button,targets:clusterTargets[index]?[clusterTargets[index]]:[]}));}return buttons.map((button,index)=>({index:index+1,button,targets:findClassTargets(scope,switcherName,index+1)}));}function setButtonState(button,active){button.classList.add(SELECTORS.button);button.classList.toggle(SELECTORS.active,active);button.classList.toggle(SELECTORS.inactive,!active);button.setAttribute('aria-pressed',active?'true':'false');}function setTargetState(target,active){target.classList.add(SELECTORS.panel);target.classList.toggle(SELECTORS.active,active);target.classList.toggle(SELECTORS.inactive,!active);target.hidden=!active;target.setAttribute('aria-hidden',active?'false':'true');}function normalizeIndex(index,groupCount){const numeric=parseInt(index,10);if(!Number.isFinite(numeric)||numeric<1)return 1;if(numeric>groupCount)return groupCount||1;return numeric;}function setActiveIndex(instance,index){const activeIndex=normalizeIndex(index,instance.groups.length);instance.activeIndex=activeIndex;instance.groups.forEach((group,groupIndex)=>{const active=groupIndex+1===activeIndex;setButtonState(group.button,active);group.targets.forEach(target=>setTargetState(target,active));});}function handleButtonClick(instance,index,event){event.preventDefault();event.stopPropagation();event.stopImmediatePropagation();setActiveIndex(instance,index);}function buildInstance(controller){const switcherName=(controller.getAttribute('data-switcher')||'').trim();if(!switcherName){warn('empty data-switcher value; controller skipped',controller);return null;}if(!safeNamePattern.test(switcherName)){warn(`invalid data-switcher value "${switcherName}"; controller skipped`,controller);return null;}const buttons=getButtons(controller);if(!buttons.length){warn(`no buttons found for "${switcherName}"; controller skipped`,controller);return null;}const mode=getMode(controller);if(mode!=='class-index'&&mode!=='cluster'){warn(`unsupported mode "${mode}" for "${switcherName}"; controller skipped`,controller);return null;}const scope=getScope(controller,mode);const groups=buildGroups(scope,switcherName,buttons,mode,controller);const foundTargetCount=groups.reduce((count,group)=>count+group.targets.length,0);if(foundTargetCount===0){warn(`no targets found for "${switcherName}"`,controller);}const missingGroups=groups.filter(group=>!group.targets.length).map(group=>group.index);if(missingGroups.length){warn(`missing targets for "${switcherName}" indexes: ${missingGroups.join(', ')}`,controller);}const instance={name:switcherName,mode,controller,scope,groups,activeIndex:normalizeIndex(CONFIG.defaultIndex,groups.length)};controller.classList.add(SELECTORS.controller);controller.setAttribute('role','group');buttons.forEach((button,index)=>{if(button.dataset.switcherBound==='true')return;button.dataset.switcherBound='true';button.addEventListener('click',event=>handleButtonClick(instance,index+1,event),true);});setActiveIndex(instance,instance.activeIndex);return instance;}function initController(controller){const existing=instances.get(controller);if(existing){setActiveIndex(existing,existing.activeIndex);return existing;}const instance=buildInstance(controller);if(instance){instances.set(controller,instance);}return instance;}function init(){if(CONFIG.enabled===false)return;document.querySelectorAll(CONFIG.controllerSelector).forEach(initController);}function resolveInstance(controllerOrName){if(controllerOrName&&controllerOrName.nodeType===1){return instances.get(controllerOrName)||initController(controllerOrName);}if(typeof controllerOrName==='string'){const controller=document.querySelector(`${CONFIG.controllerSelector}[data-switcher="${cssEscape(controllerOrName)}"]`);return controller?(instances.get(controller)||initController(controller)):null;}return null;}window.CarrdSwitcher={refresh:function(){init();},show:function(controllerOrName,index){const instance=resolveInstance(controllerOrName);if(!instance)return;setActiveIndex(instance,index);},next:function(controllerOrName){const instance=resolveInstance(controllerOrName);if(!instance)return;const nextIndex=instance.activeIndex>=instance.groups.length?1:instance.activeIndex+1;setActiveIndex(instance,nextIndex);},prev:function(controllerOrName){const instance=resolveInstance(controllerOrName);if(!instance)return;const prevIndex=instance.activeIndex<=1?instance.groups.length:instance.activeIndex-1;setActiveIndex(instance,prevIndex);}};if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();